package studio.jiayu.neo;
import android.app.*;
import android.content.DialogInterface;
import android.os.*;
import android.net.Uri;
import org.json.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
/** Scoped Studio file transfer, using the official page's own logged-in fetch context. */
final class CloudProjects {
 final MainActivity a;boolean running;int generation;ProgressDialog dialog;
 interface Result{void accept(JSONObject r)throws Exception;}
 CloudProjects(MainActivity a){this.a=a;}
 void available()throws Exception{if(running||a.projectChangeBusy()||a.studioUsage.running)throw new Exception("请先结束当前AI、联动、构建或同步任务");String u=a.studio.getUrl();if(u==null||!"https".equals(Uri.parse(u).getScheme())||!"studio.stepx.com".equals(Uri.parse(u).getHost())){a.show("studio");throw new Exception("请先打开并登录官方 Studio，再同步");}}
 JSONObject op(String action)throws Exception{return new JSONObject().put("action",action);}
 void list(){try{available();execute(op("list"),r->{JSONArray ps=r.getJSONArray("projects");if(ps.length()==0){a.toast("当前账号还没有云端项目");return;}String[]labels=new String[ps.length()];for(int i=0;i<ps.length();i++)labels[i]=ps.getJSONObject(i).optString("name");new AlertDialog.Builder(a).setTitle("同步云端项目到本地").setItems(labels,(d,n)->{try{pull(ps.getJSONObject(n).getString("id"));}catch(Exception e){fail(e);}}).setNegativeButton("取消",null).show();});}catch(Exception e){fail(e);}}
 JSONObject find(String cloudId)throws Exception{JSONArray ps=a.state.getJSONArray("projects");for(int i=0;i<ps.length();i++){JSONObject p=ps.getJSONObject(i),c=p.optJSONObject("cloud");if(c!=null&&cloudId.equals(c.optString("id")))return p;}return null;}
 void pullLocal(String id)throws Exception{JSONObject p=a.byId("projects",id),c=p.optJSONObject("cloud");if(c==null){list();return;}pull(c.getString("id"));}
 void pull(String id)throws Exception{available();JSONObject old=find(id);final String localId=old==null?"":old.getString("id");final JSONObject before=old==null?new JSONObject():CloudFiles.entries(old);
  execute(op("pull").put("projectId",id),r->{JSONObject remote=r.getJSONObject("entries"),meta=r.getJSONObject("project");CloudFiles.validate(remote);JSONObject p;
   synchronized(a){JSONObject backup=new JSONObject(a.state.toString());try{if(localId.isEmpty()){p=new JSONObject().put("id",UUID.randomUUID().toString()).put("name",meta.getString("name")).put("files",new JSONObject()).put("cloudSource",true);}else{p=new JSONObject(a.byId("projects",localId).toString());if(!ProjectEdits.same(CloudFiles.hashes(before),CloudFiles.hashes(CloudFiles.entries(p))))throw new Exception("同步期间本地文件已修改，没有覆盖");}
    JSONObject c=p.optJSONObject("cloud"),base=c==null?new JSONObject():c.optJSONObject("base");if(base==null)base=new JSONObject();JSONObject merged=CloudFiles.merge(before,remote,base);if(!localId.isEmpty())CloudFiles.snapshot(p);CloudFiles.assign(p,merged);p.put("updated",System.currentTimeMillis()).put("cloudSource",true).put("studioUrl",url(meta));p.put("cloud",new JSONObject().put("id",id).put("name",meta.getString("name")).put("builderType",meta.optString("builderType","app")).put("base",CloudFiles.hashes(remote)).put("lastPull",System.currentTimeMillis()).put("skipped",r.optJSONArray("skipped")).put("message","已同步 "+remote.length()+" 个云端源文件；本地独立修改保留"));a.upsert("projects",p);
   }catch(Exception e){a.state=backup;throw e;}}
   a.sendState();a.event("projectOpen",p.getString("id"));a.toast("已同步 "+remote.length()+" 个文件"+(r.optJSONArray("skipped").length()>0?"；已排除依赖、构建产物或敏感文件，详见同步记录":""));
  });
 }
 String url(JSONObject m){return "https://studio.stepx.com/builder/"+(Arrays.asList("app","agent","skill").contains(m.optString("builderType"))?m.optString("builderType"):"app")+"/"+m.optString("id");}
 void upload(String localId)throws Exception{available();JSONObject p=a.byId("projects",localId);CloudFiles.entries(p);JSONObject c=p.optJSONObject("cloud");if(c==null){new AlertDialog.Builder(a).setTitle("上传项目到 Studio").setMessage("将“"+p.optString("name")+"”的源码上传为新的云端项目，不发送AI生成任务。首次上传后自动关联，之后可一键继续上传。\n账号需已登录；请暂停 Studio 中的生成任务。").setPositiveButton("新建并上传",(d,n)->{try{create(localId);}catch(Exception e){fail(e);}}).setNegativeButton("取消",null).show();}else prepareUpload(localId,c.getString("id"));}
 void create(String localId)throws Exception{available();JSONObject p=a.byId("projects",localId);execute(op("create").put("name",p.optString("name")),r->{JSONObject meta=r.getJSONObject("project");JSONObject target=a.byId("projects",localId);target.put("studioUrl",url(meta)).put("cloud",new JSONObject().put("id",meta.getString("id")).put("name",meta.getString("name")).put("builderType",meta.optString("builderType","app")).put("base",new JSONObject()).put("newUpload",true).put("message","云端项目已创建，上传尚未完成；重试会继续此项目"));a.saveState();a.sendState();openNewUpload(localId,meta.getString("id"),url(meta));});}
 void openNewUpload(String localId,String id,String url){a.show("studio");a.studio.loadUrl(url);running=true;int token=++generation;awaitPage(localId,id,url,token,0);}
 void awaitPage(String localId,String id,String url,int token,int tries){new Handler(a.getMainLooper()).postDelayed(()->{if(token!=generation||a.isDestroyed())return;if(tries>=60){running=false;fail(new Exception("云端项目已创建，请稍后再次上传；不会重复创建"));return;}a.studio.evaluateJavascript("({url:location.href,ready:document.readyState})",raw->{if(token!=generation)return;try{JSONObject page=new JSONObject(raw);if(!url.equals(page.optString("url"))||!page.optString("ready").equals("complete")){awaitPage(localId,id,url,token,tries+1);return;}running=false;prepareUpload(localId,id);}catch(Exception e){running=false;fail(e);}});},500);}
 void prepareUpload(String localId,String id)throws Exception{available();final JSONObject source=CloudFiles.entries(a.byId("projects",localId));if(source.length()==0)throw new Exception("项目没有可上传文件");
  execute(op("pull").put("projectId",id).put("initialize",a.byId("projects",localId).getJSONObject("cloud").optBoolean("newUpload")),r->{JSONObject target=a.byId("projects",localId),c=target.getJSONObject("cloud");if(!id.equals(c.getString("id")))throw new Exception("项目关联已变化");JSONObject remote=r.getJSONObject("entries"),expected=CloudFiles.hashes(remote),base=c.getJSONObject("base"),changes=new JSONObject();CloudFiles.validate(remote);if(c.optBoolean("newUpload")&&!c.optBoolean("prepared")){for(Iterator<String>it=source.keys();it.hasNext();){String n=it.next();if(expected.has(n))base.put(n,expected.get(n));}c.put("prepared",true);a.saveState();}ArrayList<String>conflicts=new ArrayList<>();
   for(Iterator<String>i=source.keys();i.hasNext();){String n=i.next(),l=CloudFiles.h(source,n),v=CloudFiles.h(remote,n);if(l.equals(v))continue;if(!v.equals(base.optString(n,"")))conflicts.add(n);else changes.put(n,source.get(n));}
   if(!conflicts.isEmpty())throw new Exception("云端文件已变化，请先同步到本地解决冲突："+String.join("、",conflicts));
   if(changes.length()==0){recordUpload(localId,id,source,remote,new JSONArray(),true);a.toast("文件内容一致，无需上传");return;}
   available();if(!ProjectEdits.same(CloudFiles.hashes(source),CloudFiles.hashes(CloudFiles.entries(a.byId("projects",localId)))))throw new Exception("本地文件已变化，请重新上传");execute(op("upload").put("projectId",id).put("entries",changes).put("expected",expected),out->{JSONArray written=out.getJSONArray("written");recordUpload(localId,id,source,remote,written,out.optBoolean("complete"));if(!out.optBoolean("complete")){a.byId("projects",localId).getJSONObject("cloud").put("message",out.optString("error"));a.saveState();a.sendState();a.event("cloudUpdated",localId);throw new Exception(out.optString("error"));}a.toast("上传完成，已回读核验 "+written.length()+" 个文件");});
  });
 }
 void recordUpload(String localId,String id,JSONObject source,JSONObject remote,JSONArray written,boolean complete)throws Exception{JSONObject p=a.byId("projects",localId),c=p.getJSONObject("cloud");if(!id.equals(c.getString("id")))throw new Exception("项目关联已变化");JSONObject base=c.getJSONObject("base");for(Iterator<String>i=source.keys();i.hasNext();){String n=i.next();if(CloudFiles.h(source,n).equals(CloudFiles.h(remote,n)))base.put(n,CloudFiles.h(source,n));}for(int i=0;i<written.length();i++){String n=written.getString(i);base.put(n,CloudFiles.h(source,n));}c.put("base",base).put("lastUpload",System.currentTimeMillis()).put("message",complete?"上传完成，文件已回读核验":"上传未完成，已核验 "+written.length()+" 个文件；请重新核对后继续");if(complete)c.remove("newUpload");a.saveState();a.sendState();a.event("cloudUpdated",localId);}
 void execute(JSONObject op,Result result)throws Exception{if(running)throw new Exception("同步进行中");String js=new String(MainActivity.readLimited(a.getAssets().open("cloud-projects.js"),64000),StandardCharsets.UTF_8),url=a.studio.getUrl();running=true;int id=++generation;dialog=new ProgressDialog(a);dialog.setTitle("Studio 项目同步");dialog.setMessage("正在连接…");dialog.setCancelable(false);dialog.setButton(DialogInterface.BUTTON_NEGATIVE,"停止",(d,n)->cancel());dialog.show();
  a.studio.evaluateJavascript("(()=>{"+js+";window.__neoCloudController=new AbortController();window.__neoCloudResult=null;window.__neoCloudProgress='连接云端';NeoCloud.run("+op+",window.__neoCloudController.signal,p=>window.__neoCloudProgress=p).then(r=>window.__neoCloudResult={ok:true,data:r}).catch(e=>window.__neoCloudResult={ok:false,error:e.message});})();void 0",null);poll(id,url,System.currentTimeMillis()+240000,result);
 }
 void poll(int id,String url,long deadline,Result callback){new Handler(a.getMainLooper()).postDelayed(()->{if(id!=generation||a.isDestroyed())return;if(!Objects.equals(url,a.studio.getUrl())){finish();fail(new Exception("Studio 页面已变化；若在上传，请重新核对云端文件"));return;}a.studio.evaluateJavascript("({result:window.__neoCloudResult||null,progress:window.__neoCloudProgress||''})",s->{if(id!=generation)return;try{JSONObject v=new JSONObject(s);if(dialog!=null)dialog.setMessage(v.optString("progress"));if(v.isNull("result")){if(System.currentTimeMillis()>deadline){if(System.currentTimeMillis()>deadline+5000){++generation;finish();fail(new Exception("同步超时；上传结果可能部分完成，请重新核对云端文件"));return;}cancel();}poll(id,url,deadline,callback);return;}JSONObject r=v.getJSONObject("result");finish();if(!r.optBoolean("ok"))throw new Exception(r.optString("error"));callback.accept(r.getJSONObject("data"));}catch(Exception e){finish();fail(e);}});},250);}
 void finish(){running=false;if(dialog!=null){dialog.dismiss();dialog=null;}a.studio.evaluateJavascript("delete window.__neoCloudResult;delete window.__neoCloudProgress;delete window.__neoCloudController;void 0",null);}
 void cancel(){if(!running)return;a.studio.evaluateJavascript("window.__neoCloudController?.abort();void 0",null);/* Let in-flight upload report verified files before closing. */if(dialog!=null)dialog.setMessage("正在停止；核对已完成文件…");}
 void destroy(){++generation;running=false;if(dialog!=null)dialog.dismiss();}
 void fail(Exception e){a.event("cloudError",a.safeError(e));a.toast(a.safeError(e));if(a.debug)android.util.Log.w("NeoCloud",a.safeError(e));}
}
